source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    height, width = len(out), len(out[0])
    background = Counter(cell for row in out for cell in row).most_common(1)[0][0]
    seen = set()

    for r in range(height):
        for c in range(width):
            color = out[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= yy < height and 0 <= xx < width and
                            (yy, xx) not in seen and out[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            top = min(y for y, _ in component)
            bottom = max(y for y, _ in component)
            left = min(x for _, x in component)
            right = max(x for _, x in component)
            if bottom - top < 2 or right - left < 2:
                continue
            border = ((y, x) for y in range(top, bottom + 1)
                      for x in range(left, right + 1)
                      if y in (top, bottom) or x in (left, right))
            inner_area = (bottom - top - 1) * (right - left - 1)
            if all(out[y][x] == color for y, x in border) and all(
                    out[y][x] == background
                    for y in range(top + 1, bottom)
                    for x in range(left + 1, right)):
                fill = 7 if inner_area % 2 else 2
                for y in range(top + 1, bottom):
                    for x in range(left + 1, right):
                        out[y][x] = fill
    return out
